<script>
  // Simple interactive toggle simulation for live controls
  let streamRunning = true;
  function toggleStream() {
    streamRunning = !streamRunning;
    const label = document.getElementById('streamToggleLabel');
    const icon = document.getElementById('streamToggleIcon');
    if (streamRunning) {
      label.innerText = 'Pause Stream';
      icon.innerText = 'pause_circle';
      icon.className = 'material-symbols-outlined text-[18px] text-primary';
    } else {
      label.innerText = 'Resume Stream';
      icon.innerText = 'play_circle';
      icon.className = 'material-symbols-outlined text-[18px] text-tertiary';
    }
  }

  let soundActive = true;
  function toggleSound() {
    soundActive = !soundActive;
    const label = document.getElementById('soundToggleLabel');
    const icon = document.getElementById('soundToggleIcon');
    if (soundActive) {
      label.innerText = 'Audio Alerts (On)';
      icon.innerText = 'volume_up';
      icon.className = 'material-symbols-outlined text-[18px] text-tertiary';
    } else {
      label.innerText = 'Audio Alerts (Muted)';
      icon.innerText = 'volume_off';
      icon.className = 'material-symbols-outlined text-[18px] text-outline';
    }
  }

  // Real-time clock ticker
  setInterval(() => {
    const el = document.getElementById('currentTimeTicker');
    if (el) {
      const now = new Date();
      el.innerText = now.toLocaleTimeString() + ' EST';
    }
  }, 1000);
</script></main></div>
